export type CreateRefundRequest = ({ "amount_money"?: MoneyValue; "charges"?: Array<RefundCharge>; /** Caller-owned identifier for this resource in an external system. minLength: 1. maxLength: 255. */ "external_reference_id"?: string; /** Original standalone gift card funding load paid by a Flint payment. Refunds its paid consideration and removes the corresponding eligible unspent face value. Requires Idempotency-Key; cannot be combined with order, line item, charge, tax or tender targets. pattern: ^gcl_[0-9A-HJKMNP-TV-Z]{26}$. */ "gift_card_load_id"?: string; "line_items"?: Array<RefundLineItem>; "metadata"?: Record<string, string>; "order_id"?: string; "payment_intent_id"?: string; /** Optional. When omitted, no reason is recorded or sent to the processor, and the buyer's refund email has no reason line. */ "reason"?: "duplicate" | "fraudulent" | "requested_by_customer" | "defective_product" | "wrong_item_shipped" | "never_received" | "not_as_described" | "arrived_too_late" | "customer_changed_mind" | "better_price_found" | "accidental_order" | "other" | (string & {}); "reason_message"?: string; "refund_method"?: "original_payment" | (string & {}); "tax_breakdown_refunds"?: Array<RefundTaxBreakdownRefundIn>; /** Exhaustive allocations to original tenders. Amounts sum to amount_money when supplied; otherwise their sum determines the refund. Selected line-item, charge and flat-tax components must be covered by their original tenders. Additional untargeted value follows the default tender order. Gift card destinations default to original. Select replacement when the original card is closed or cannot accept the full credit within its balance cap. minItems: 1. maxItems: 21. */ "tender_allocations"?: Array<RefundTenderAllocationRequest>; }) & (({ "order_id": unknown; }) | ({ "payment_intent_id": unknown; }) | ({ "tender_allocations": unknown; }) | ({ "gift_card_load_id": unknown; }) | (object));
